  KEENEYE = { abilityId = 51, behaviour = { chance = 100, effects = { { kind = "prevent", what = "this Pokémon's accuracy from being lowered by stat modifiers" } }, expressible = true, notes = "Does not block other accuracy-lowering sources such as fog or foe evasion. Overworld: if this is the lead Pokémon, a 50% chance to skip random encounters 5+ levels below it.", scope = "self", trigger = "passive" }, effect = "This Pokémon cannot have its accuracy lowered. This ability does not prevent any accuracy losses other than stat modifiers, such as the accuracy cut from fog; nor does it prevent other Pokémon's evasion from making this Pokémon's moves less accurate. This Pokémon can still be passed negative accuracy modifiers through Heart Swap. Overworld: If the first Pokémon in the party has this ability, any random encounter with a Pokémon five or more levels lower than it has a 50% chance of being skipped.", effectChanges = { { effect = "Has no overworld effect.", versionGroup = "emerald" } }, generation = "generation-iii", id = "KEENEYE", name = "Keen Eye", shortEffect = "Prevents accuracy from being lowered.", slug = "keen-eye", speciesCount = 43 },
  KLUTZ = { abilityId = 103, behaviour = { chance = 100, effects = { { kind = "prevent", what = "using or benefiting from its held item in battle, including Fling" } }, expressible = true, notes = "Effort items' Speed effects (Iron Ball, Macho Brace, Power items) and non-battle passive items (Exp. Share, Amulet Coin, Soothe Bell) are unaffected; item-based moves like Natural Gift/Switcheroo still work; item functions normally outside battle.", scope = "self", trigger = "passive" }, effect = "In battle, this Pokémon cannot use its held item, nor will the item have any passive effect on the battle, positive or negative. This Pokémon also cannot use Fling. The Speed cut from the Iron Ball and the effort items (the Macho Brace, Power Weight, Power Bracer, Power Belt, Power Lens, Power Band, and Power Anklet) is unaffected. Items that do not directly affect the battle, such as the Exp. Share, the Amulet Coin, or the Soothe Bell, work as usual. All held items work as usual out of battle. Other moves that use the held item, such as Natural Gift and Switcheroo, work as usual.", effectChanges = { { effect = "Fling can be used as usual.", versionGroup = "black-white" } }, generation = "generation-iv", id = "KLUTZ", name = "Klutz", shortEffect = "Prevents the Pokémon from using its held item in battle.", slug = "klutz", speciesCount = 12 },
  LEAFGUARD = { abilityId = 102, behaviour = { chance = 100, effects = { { kind = "status_immunity", status = "burn" }, { kind = "status_immunity", status = "freeze" }, { kind = "status_immunity", status = "paralysis" }, { kind = "status_immunity", status = "poison" }, { kind = "status_immunity", status = "toxic" }, { kind = "status_immunity", status = "sleep" } }, expressible = false, notes = "Immunity is active only during harsh sunlight, not permanent as status_immunity implies, and does not cure a pre-existing ailment. Rest fails outright, and Yawn fails or whiffs while sunlight is active.", scope = "self", trigger = "on_weather" }, effect = "This Pokémon cannot be given a major status ailment during strong sunlight. This ability does not heal prior status ailments. Rest will fail altogether with this ability in effect. Yawn will immediately fail if used on this Pokémon during strong sunlight, and an already-used Yawn will fail if the weather turns to strong sunlight in the meantime.", effectChanges = { { effect = "Rest works as usual during strong sunlight.", versionGroup = "black-white" } }, generation = "generation-iv", id = "LEAFGUARD", name = "Leaf Guard", shortEffect = "Protects against major status ailments during strong sunlight.", slug = "leaf-guard", speciesCount = 23 },
