  LIGHTMETAL = { abilityId = 135, behaviour = { chance = 100, effects = { { kind = "other", what = "halves this Pokémon's weight for weight-based effects" } }, expressible = false, notes = "Weight is not a modeled quantity, so weight-based interactions (Grass Knot, Low Kick, Heat Crash, etc.) can't be expressed with a dedicated kind.", scope = "self", trigger = "passive" }, effect = "This Pokémon has half the usual weight for its species.", effectChanges = {}, generation = "generation-v", id = "LIGHTMETAL", name = "Light Metal", shortEffect = "Halves the Pokémon's weight.", slug = "light-metal", speciesCount = 7 },
  LIGHTNINGROD = { abilityId = 31, behaviour = { chance = 100, effects = { { kind = "stat_change", stages = 1, stat = "special-attack" } }, expressible = false, notes = "Also redirects other Pokémon's single-target Electric-type moves to this Pokémon when eligible (highest Speed wins ties randomly; not redirected if the original target also has Lightning Rod; Follow Me takes precedence) — redirection isn't modeled. The stat rise negates the move's other effects and cannot miss; a Ground-type immune to Electric does not get the boost.", scope = "self", trigger = "on_hit_taken" }, effect = "All other Pokémon's single-target Electric-type moves are redirected to this Pokémon if it is an eligible target. Other Pokémon's Electric moves raise this Pokémon's Special Attack one stage, negating any other effect on it, and cannot miss it. If the move's intended target also has this ability, the move is not redirected. When multiple Pokémon with this ability are possible targets for redirection, the move is redirected to the one with the highest Speed stat, or, in the case of a tie, to a random tied Pokémon. Follow Me takes precedence over this ability. If the Pokémon is a Ground-type and thus immune to Electric moves, its immunity prevents the Special Attack boost.", effectChanges = { { effect = "Has no overworld effect.", versionGroup = "emerald" }, { effect = "Does not affect non-damaging Electric moves, i.e. Thunder Wave. Increases the frequency of Match Call calls on the overworld if any party Pokémon has this ability.", versionGroup = "diamond-pearl" }, { effect = "Redirects Electric moves without negating them or granting any Special Attack boost. Does not redirect Hidden Power.", versionGroup = "black-white" } }, generation = "generation-iii", id = "LIGHTNINGROD", name = "Lightning Rod", shortEffect = "Redirects single-target Electric moves to this Pokémon where possible. Absorbs Electric moves, raising Special Attack one stage.", slug = "lightning-rod", speciesCount =