  LIQUIDOOZE = { abilityId = 64, behaviour = { chance = 100, effects = { { kind = "other", what = "the attacker takes damage equal to the HP it would have drained, instead of healing" } }, expressible = false, notes = "No 'reverse heal to damage' kind exists. Dream Eater is unaffected by this ability.", scope = "target", trigger = "on_hit_taken" }, effect = "Whenever a Pokémon would heal after hitting this Pokémon with a leeching move like Absorb, it instead loses as many HP as it would usually gain. Dream Eater is unaffected.", effectChanges = {}, generation = "generation-iii", id = "LIQUIDOOZE", name = "Liquid Ooze", shortEffect = "Damages opponents using leeching moves for as much as they would heal.", slug = "liquid-ooze", speciesCount = 4 },
