  MAGICBOUNCE = { abilityId = 156, behaviour = { chance = 100, effects = { { kind = "other", what = "redirects the move back onto its user instead of hitting this Pokémon" } }, expressible = false, notes = "Only applies to moves flagged as reflectable (most non-damaging moves that target another Pokémon); a move already reflected by Magic Bounce or Magic Coat cannot be bounced again. No 'redirect move back to user' kind exists.", scope = "target", trigger = "on_hit_taken" }, effect = "When this Pokémon is targeted by a move flagged as being reflectable, the move is redirected to its user. All reflectable moves are non-damaging, and most non-damaging moves that target other Pokémon are reflectable. A move reflected by this ability or Magic Coat cannot be reflected back.", effectChanges = {}, generation = "generation-v", id = "MAGICBOUNCE", name = "Magic Bounce", shortEffect = "Reflects most non-damaging moves back at their user.", slug = "magic-bounce", speciesCount = 11 },
  MAGICGUARD = { abilityId = 98, behaviour = { chance = 100, effects = { { kind = "other", what = "immune to damage and effects not directly caused by a move: weather, recoil, status damage, entry hazards, Leech Seed drain, and similar" } }, expressible = false, notes = "Struggle, Pain Split, Belly Drum, Substitute, Curse, self-KO moves (e.g. Explosion), and confusion damage still work normally; burn's Attack drop still applies; a Life Orb still boosts moves without recoil; the badly-poisoned counter still climbs each turn even though no damage is taken. No kind covers this breadth of indirect-damage immunity.", scope = "self", trigger = "passive" }, effect = "This Pokémon is immune to damage not directly caused by a move. For example, this Pokémon takes no damage from from weather, recoil, status ailments, or Spikes, but it still suffers from the Attack cut when burned, and a Life Orb will still power up this Pokémon's moves without damaging it. Anything that directly depends on such damage will also not happen; for example, Leech Seed will neither hurt this Pokémon nor heal the opponent, and Pokémon with a Jaboca Berry or Rowap Berry will not consume the berry when hit by this Pokémon. The following are unaffected: Struggle, Pain Split (whether used by or against this Pokémon), Belly Drum, Substitute, Curse, moves that knock the user out, and damage from confusion. This Pokémon will neither lose nor regain HP if it drains HP from a Pokémon with Liquid Ooze. If this Pokémon is badly poisoned, the poison counter is still increased each turn; if the Pokémon loses this ability, it will begin taking as much damage as it would be if it had been taking increasing damage each turn.", effectChanges = { { effect = "Paralysis cannot prevent the Pokémon from moving, though the Speed cut is unaffected. Poison still damages the Pokémon outside of battle.", versionGroup = "black-white" } }, generation = "generation-iv", id = "MAGICGUARD", name = "Magic Guard", shortEffect = "Protects against damage not directly caused by a move.", slug = "magic-guard", speciesCount = 10 },
