  MAGMAARMOR = { abilityId = 40, behaviour = { chance = 100, effects = { { kind = "status_immunity", status = "freeze" } }, expressible = true, notes = "Overworld: any party Pokémon with this ability (or Flame Body) halves each egg's step-cycle hatch counter contribution by reducing it by 2 instead of 1 per step cycle; does not stack between multiple qualifying Pokémon.", scope = "self", trigger = "passive" }, effect = "This Pokémon cannot be frozen. If a Pokémon is frozen and acquires this ability, it will immediately thaw out; this includes when regaining a lost ability upon leaving battle. Overworld: If any Pokémon in the party has this ability, each egg in the party has its hatch counter decreased by 2 (rather than 1) each step cycle, making eggs hatch roughly twice as quickly. This effect does not stack if multiple Pokémon have this ability or Flame Body.", effectChanges = { { effect = "Has no overworld effect.", versionGroup = "emerald" } }, generation = "generation-iii", id = "MAGMAARMOR", name = "Magma Armor", shortEffect = "Prevents freezing.", slug = "magma-armor", speciesCount = 3 },
  MAGNETPULL = { abilityId = 42, behaviour = { chance = 100, effects = { { kind = "prevent", what = "opposing Steel-type Pokémon from fleeing or switching out via the menu (Run Away, and switching via move or item, still work)" } }, expressible = true, notes = "Overworld: if this is the lead Pokémon, Steel-type wild encounters occur more often.", scope = "foes", trigger = "passive" }, effect = "While this Pokémon is in battle, opposing Steel-type Pokémon cannot flee or switch out. Pokémon with Run Away can still flee. Pokémon can still switch out with the use of a move or item. Overworld: If the lead Pokémon has this ability, Steel-type Pokémon have a higher encounter rate.", effectChanges = { { effect = "Has no overworld effect.", versionGroup = "emerald" } }, generation = "generation-iii", id = "MAGNETPULL", name = "Magnet Pull", shortEffect = "Prevents Steel opponents from fleeing or switching out.", slug = "magnet-pull", speciesCount = 9 },
  MARVELSCALE = { abilityId = 63, behaviour = { chance = 100, effects = { { factor = 1.5, kind = "stat_multiplier", stat = "defense" } }, expressible = false, notes = "Multiplier only applies while this Pokémon has a major status ailment; stat_multiplier has no conditional field to express that, and the bonus does not count as a stat stage change.", scope = "self", trigger = "passive" }, effect = "Whenever this Pokémon has a major status ailment, it has 1.5× its Defense. This bonus does not count as a stat modifier.", effectChanges = {}, generation = "generation-iii", id = "MARVELSCALE", name = "Marvel Scale", shortEffect = "Increases Defense to 1.5× with a major status ailment.", slug = "marvel-scale", speciesCount = 3 },
  MEGALAUNCHER = { abilityId = 178, behaviour = { chance = 100, effects = { { factor = 1.5, kind = "damage_dealt_multiplier", when = "move is aura- or pulse-flagged" } }, expressible = true, notes = "", scope = "self", trigger = "passive" }, effect = "Strengthens aura and pulse moves to 1.5× their power.", effectChanges = {}, generation = "generation-vi", id = "MEGALAUNCHER", name = "Mega Launcher", shortEffect = "Strengthens aura and pulse moves to 1.5× their power.", slug = "mega-launcher", speciesCount = 3 },
  MEGASOL = { abilityId = 310, behaviour = { chance = 100, effects = { { kind = "other", what = "treats the weather as harsh sunlight for its own moves, even when it is not actually sunny" } }, expressible = false, notes = "No kind expresses a personal, simulated weather state distinct from set_weather, which would change the field weather for everyone rather than just this Pokémon's own moves.", scope = "self", trigger = "passive" }, effect = "Even when the sunlight has not turned harsh, the Pokémon can use its moves as if the weather were harsh sunlight.", effectChanges = {}, generation = "generation-ix", id = "MEGASOL", name = "Mega Sol", shortEffect = "The Pokémon can use its moves as if the weather were harsh sunlight.", slug = "mega-sol", speciesCount = 1 },
