  MIMICRY = { abilityId = 250, behaviour = { chance = 100, effects = { { kind = "change_type", to = "the type matching the currently active terrain (Normal if no terrain is active)" } }, expressible = true, notes = "", scope = "self", trigger = "passive" }, effect = "Changes the Pokémon’s type depending on the terrain.", effectChanges = {}, generation = "generation-viii", id = "MIMICRY", name = "Mimicry", shortEffect = "Changes type depending on the terrain.", slug = "mimicry", speciesCount = 1 },
  MINDSEYE = { abilityId = 299, behaviour = { chance = 100, effects = { { kind = "other", what = "Normal- and Fighting-type moves used by this Pokémon can hit Ghost-type Pokémon" }, { kind = "prevent", what = "this Pokémon's accuracy from being lowered" }, { kind = "other", what = "ignores changes to the opposing Pokémon's evasion stat" } }, expressible = false, notes = "The Ghost-type-hit bypass and the evasion-ignoring effect have no dedicated kind; approximated with 'other'.", scope = "self", trigger = "passive" }, effect = "Mind's Eye enables the Pokémon with this Ability to hit Ghost-type Pokémon with damage-dealing Normal- and Fighting-type moves. It also prevents other Pokémon from lowering the Pokémon's accuracy and ignores changes to the opponents' evasion.", effectChanges = {}, generation = "generation-ix", id = "MINDSEYE", name = "Mind’s Eye", shortEffect = "The Pokémon ignores changes to opponents' evasiveness, its accuracy can't be lowered, and it can hit Ghost types with Normal- and Fighting-type moves.", slug = "minds-eye", speciesCount = 1 },
  MINUS = { abilityId = 58, behaviour = { chance = 100, effects = { { factor = 1.5, kind = "stat_multiplier", stat = "special-attack" } }, expressible = false, notes = "Multiplier only applies while an ally on the field has Plus or Minus; if either ability is suppressed by Gastro Acid, both lose the bonus. stat_multiplier has no conditional field for this, and the bonus does not count as a stat stage change.", scope = "self", trigger = "passive" }, effect = "This Pokémon has 1.5× its Special Attack if any friendly Pokémon has Plus or Minus. This bonus does not count as a stat modifier. If either ability is disabled by Gastro Acid, both lose their effect.", effectChanges = { { effect = "Powers up only when paired with Plus.", versionGroup = "black-white" } }, generation = "generation-iii", id = "MINUS", name = "Minus", shortEffect = "Increases Special Attack to 1.5× when a friendly Pokémon has Plus or Minus.", slug = "minus", speciesCount = 8 },
