  MISTYSURGE = { abilityId = 228, behaviour = { chance = 100, effects = { { kind = "set_terrain", terrain = "misty" } }, expressible = true, notes = "", scope = "field", trigger = "switch_in" }, effect = "When this Pokémon enters battle, it changes the terrain to Misty Terrain.", effectChanges = {}, generation = "generation-vii", id = "MISTYSURGE", name = "Misty Surge", shortEffect = "When this Pokémon enters battle, it changes the terrain to Misty Terrain.", slug = "misty-surge", speciesCount = 2 },
  MOLDBREAKER = { abilityId = 104, behaviour = { chance = 100, effects = { { kind = "other", what = "this Pokémon's moves ignore the target's ability if that ability would hinder or prevent the move's effect (e.g. move-blocking immunities like Water Absorb, protective abilities like Clear Body/Shell Armor/Sticky Hold, general protective abilities like Simple/Snow Cloak/Thick Fat, and dual-purpose abilities like Dry Skin/Unaware)" } }, expressible = false, notes = "Cannot ignore type/form-changing abilities (Color Change, Forecast), effects no longer tied to an ability (e.g. rain already summoned by Drizzle), or Multitype at all. An ignored ability still resumes immediately after the move resolves (e.g. Limber cures paralysis right after being inflicted), and already-placed hazards like Spikes are unaffected. Cursed Body, Liquid Ooze, and Shadow Tag are not ignored since they don't hinder the move itself. Functions identically to Teravolt and Turboblaze. No kind exists for this ability-ignoring mechanic.", scope = "self", trigger = "passive" }, effect = "This Pokémon's moves completely ignore abilities that could hinder or prevent their effect on the target. For example, this Pokémon's moves ignore abilities that would fully negate them, such as Water Absorb; abilities that would prevent any of their effects, such as Clear Body, Shell Armor, or Sticky Hold; and abilities that grant any general protective benefit, such as Simple, Snow Cloak, or Thick Fat. If an ability could either hinder or help this Pokémon's moves, e.g. Dry Skin or Unaware, the ability is ignored either way. Abilities that do not fit this description, even if they could hinder moves in some other way, are not affected. For example, Cursed Body only affects potential future uses of the move, while Liquid Ooze and Shadow Tag can only hinder a move's effect on the user. This ablity cannot ignore type or form changes granted by abilities, for example Color Change or Forecast; nor effects that were caused by abilities but are no longer tied to an ability, such as the rain from Drizzle. This ability cannot ignore Multitype at all. An ability ignored by this ability is only nullified while the move is being used. For example, this Pokémon's moves can paralyze a Pokémon with Limber, but Limber will activate and heal the paralysis immediately thereafter, and this Pokémon's Spikes are not affected by this ability after they have been placed. When this Pokémon enters battle, all participating trainers are notified that it has this ability. This ability functions identically to Teravolt and Turboblaze.", effectChanges = {}, generation = "generation-iv", id = "MOLDBREAKER", name = "Mold Breaker", shortEffect = "Bypasses targets' abilities if they could hinder or prevent a move.", slug = "mold-breaker", speciesCount = 27 },
  MOODY = { abilityId = 141, behaviour = { chance = 100, effects = { { kind = "other", what = "raises one random stat by 2 stages and lowers a different random stat by 1 stage each turn (stats already at +6 or -6 are excluded from being chosen)" } }, expressible = false, notes = "stat_change requires a fixed stat; Moody's randomized dual stat change has no matching kind.", scope = "self", trigger = "turn_end" }, effect = "After each turn, one of this Pokémon's stats at random rises two stages, and another falls one stage. If a stat is already at 6 or -6 stages, it will not be chosen to be increased or decreased, respectively.", effectChanges = {}, generation = "generation-v", id = "MOODY", name = "Moody", shortEffect = "Raises a random stat two stages and lowers another one stage after each turn.", slug = "moody", speciesCount = 8 },
